fn is_non_prime(n: u64) -> bool {
    // Since n >= 2 as per the problem statement
    // Check divisors from 2 up to sqrt(n) (inclusive)
    // If any divides n, return true (non-prime)
    // Otherwise return false (prime)
    if n == 2 {
        return false; // 2 is prime, no divisors other than 1 and itself
    }

    let limit = (n as f64).sqrt() as u64;
    for k in 2..=limit {
        if n % k == 0 {
            return true;
        }
    }
    false
}